def NC(id, notion, pq, prerequis, marches, image, exemple, piege, verif):
    return {"id": id, "notion": notion, "pourquoi_difficile": pq, "prerequis": prerequis,
            "marches": [{"n": i + 1, "idee": m[0], "vu": m[1], "question": m[2]} for i, m in enumerate(marches)],
            "image_mentale": image, "exemple_chiffre": exemple, "piege": piege, "verification": verif}

